/* Headless interaction checks for 09-13-hmi-touch-acceptance (T4).
 *
 * Covers a practical subset of research/interaction-cases.md that can be
 * driven by the scripted pointer indev without board touch hardware:
 *   I01 click home tile -> device
 *   I02 press + drag cancels navigation
 *   I11 filter + return restores page
 *   I12 trend window restore
 *   I17 bounded nav stack
 *   I19 discover scan switch defaults off on re-entry
 */

#include "harness_common.h"
#include "model/vg_model.h"
#include "shell/vg_shell.h"
#include "widgets/vg_confirm_dialog.h"
#include <stdio.h>
#include <string.h>

static void seed_points(int n)
{
    vg_runtime_point_t pts[32];
    int i;

    if(n > 32) n = 32;
    memset(pts, 0, sizeof(pts));
    for(i = 0; i < n; i++) {
        snprintf(pts[i].id, sizeof(pts[i].id), "PT%02d", i);
        snprintf(pts[i].name, sizeof(pts[i].name), "点位%02d", i);
        pts[i].addr = 1;
        pts[i].fc = 3;
        pts[i].reg = (uint16_t)(100 + i);
        snprintf(pts[i].unit, sizeof(pts[i].unit), "C");
        snprintf(pts[i].dtype, sizeof(pts[i].dtype), "uint16");
        pts[i].scale = 1.0f;
        snprintf(pts[i].cmp, sizeof(pts[i].cmp), "ge");
        pts[i].fail_n = 3;
    }
    vg_model_import_runtime_points(pts, (uint16_t)n);
    for(i = 0; i < n; i++) {
        vg_model_set_live(i, 20.0f + (float)i, true);
    }
    hg_pump(5);
}

int main(int argc, char ** argv)
{
    const char * out_dir = (argc > 1) ? argv[1] : ".";
    bool ok = true;
    int cx = 0, cy = 0;
    int i;

    (void)out_dir;
    hg_init();
    seed_points(16);

    /* I01: tap first home tile enters device once */
    ok &= hg_expect(vg_nav_current() == VG_PAGE_HOME, "start on home");
    ok &= hg_expect(hg_find_row_click_point("点位00", 0, &cx, &cy),
                    "locate first home tile");
    hg_queue_click(cx, cy);
    hg_pump(12);
    ok &= hg_expect(vg_nav_current() == VG_PAGE_DEVICE, "I01 click opens device");
    vg_nav_back();
    hg_pump(6);
    ok &= hg_expect(vg_nav_current() == VG_PAGE_HOME, "back to home");

    /* I02: press then drag should scroll, not open device */
    ok &= hg_expect(hg_find_row_click_point("点位00", 0, &cx, &cy),
                    "locate tile for drag");
    hg_queue_drag(cx, cy, cx, cy - 90, 10);
    hg_pump(40);
    ok &= hg_expect(vg_nav_current() == VG_PAGE_HOME,
                    "I02 drag cancels tile navigation");

    /* I11: filter offline, enter device, back stays home (filter is model state) */
    ok &= hg_expect(hg_click_btn("离线"), "click offline filter");
    hg_pump(8);
    ok &= hg_expect(vg_model_get_home_filter() == VG_HOME_FILTER_OFFLINE,
                    "I11 offline filter applied");
    /* empty offline list: open device via detail action if available */
    if(hg_click_btn("详情")) {
        hg_pump(8);
        if(vg_nav_current() == VG_PAGE_DEVICE) {
            vg_nav_back();
            hg_pump(6);
        }
    }
    ok &= hg_expect(vg_nav_current() == VG_PAGE_HOME, "I11 still on home after return");
    ok &= hg_expect(vg_model_get_home_filter() == VG_HOME_FILTER_OFFLINE,
                    "I11 filter preserved across navigation");
    ok &= hg_expect(hg_click_btn("全部"), "restore all filter");
    hg_pump(6);

    /* I12: trend window recent/all restore */
    vg_model_set_selected_sensor("PT00");
    vg_nav_goto(VG_PAGE_TREND, NULL);
    hg_pump(8);
    ok &= hg_expect(vg_nav_current() == VG_PAGE_TREND, "open trend");
    ok &= hg_expect(hg_click_btn("全部"), "select full history window");
    hg_pump(8);
    vg_nav_goto(VG_PAGE_HOME, NULL);
    hg_pump(6);
    vg_nav_back();
    hg_pump(8);
    /* Returning to trend should restore window_recent=0 via nav state. */
    ok &= hg_expect(vg_nav_current() == VG_PAGE_TREND, "I12 back restores trend page");

    /* I17: bounded stack — many goto then back should not grow forever */
    for(i = 0; i < 12; i++) {
        vg_nav_goto(VG_PAGE_ALARM, NULL);
        hg_pump(2);
        vg_nav_goto(VG_PAGE_REPORT, NULL);
        hg_pump(2);
        vg_nav_goto(VG_PAGE_HOME, NULL);
        hg_pump(2);
    }
    for(i = 0; i < 20; i++) {
        vg_nav_back();
        hg_pump(2);
    }
    ok &= hg_expect(vg_nav_current() == VG_PAGE_HOME,
                    "I17 bounded back ends at home");

    /* I18: confirm dialog closes before page back */
    vg_nav_goto(VG_PAGE_DISCOVER, NULL);
    hg_pump(8);
    /* Open a confirm if the page exposes one; otherwise skip soft. */
    if(vg_confirm_dialog_is_open() || hg_click_btn("写入点表")) {
        hg_pump(8);
        if(vg_confirm_dialog_is_open()) {
            vg_nav_back();
            hg_pump(4);
            ok &= hg_expect(!vg_confirm_dialog_is_open(),
                            "I18 back closes confirm first");
            ok &= hg_expect(vg_nav_current() == VG_PAGE_DISCOVER,
                            "I18 still on discover after closing confirm");
        }
    }

    /* I19: leave discover and return — scan switch must stay default off */
    vg_nav_goto(VG_PAGE_HOME, NULL);
    hg_pump(4);
    vg_nav_goto(VG_PAGE_DISCOVER, NULL);
    hg_pump(8);
    ok &= hg_expect(vg_nav_current() == VG_PAGE_DISCOVER, "I19 re-enter discover");
    /* Scan requires explicit enable; without switch checked, start is blocked. */
    if(hg_click_btn("开始扫描")) {
        hg_pump(6);
        /* Toast path; page must remain discover and not auto-scan. */
        ok &= hg_expect(vg_nav_current() == VG_PAGE_DISCOVER,
                        "I19 scan without switch stays on page");
    }

    printf("interaction_check: %s (%d failures)\n",
           ok && hg_failures() == 0 ? "ALL PASS" : "FAIL", hg_failures());
    return (ok && hg_failures() == 0) ? 0 : 1;
}

